package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type PartRec struct {
	LbPart   string
	LbRegion string
	LbSerial int64
}

var WsEofFlag string = "N"
var WsLabel string = strings.Repeat(" ", 20)
var WsACount int64 = 0
var WsTotalA int64 = 0
var WsCount int64 = 0

var _ = decimal.NewFromInt(0)

var partRec PartRec
var partFileReader *bufio.Reader
var partFileHandle *os.File
var inputDone bool = false

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func formatPIC9(n int64, digits int) string {
	neg := n < 0
	if neg {
		n = -n
	}
	s := fmt.Sprintf("%d", n)
	if len(s) > digits {
		s = s[len(s)-digits:]
	} else if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	if neg {
		// COBOL would handle sign separately; not needed here
	}
	return s
}

func delimitedBySpace(s string) string {
	idx := strings.Index(s, " ")
	if idx == -1 {
		return s
	}
	return s[:idx]
}

func mainPara() {
	openInput()
	readPara()
	for !inputDone {
		processPara()
	}
	closeInput()
	summaryPara()
}

func readPara() {
	line, err := partFileReader.ReadString('\n')
	if err != nil {
		// Check if EOF
		if len(line) == 0 {
			WsEofFlag = "Y"
			inputDone = true
			return
		}
		// last line without newline, treat as record
	}
	// Remove trailing \r and \n
	line = strings.TrimRight(line, "\r\n")
	// Pad with spaces on right if shorter than record length
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	}
	if len(line) > 15 {
		line = line[:15]
	}
	// If we hit EOF condition: when ReadString returned EOF and line was empty, handled above
	// Otherwise if err != nil and we have a line, we still process it and next read will be EOF
	// Detect EOF for next call: if err != nil, we need to know if this was last line
	// We set flag only when ReadString returns error with no data; otherwise we process and
	// next iteration will hit EOF. So we need to look ahead.
	// Simpler: if err != nil (EOF) we have just read last line, keep it, but don't set done yet.
	// We set done on next call. However our earlier handling set done only when len==0.
	// Need to remember if we are at EOF to set done after this read? Actually COBOL READ AT END triggers only when no more records.
	// Our loop calls READ-PARA after processing; so we need to detect EOF correctly.
	// Approach: use buffered peek.
	// Instead, use a flag to check underlying EOF: if err != nil, we have consumed last line,
	// but we should not mark done now; mark done on next read attempt.
	// To achieve, we check if err != nil and we processed a line, we keep inputDone false now,
	// but next call will return EOF with empty line and set done.
	// However bufio.ReadString returns io.EOF with data if last line has no newline.
	// So we need to handle that: if err != nil and len(line) was originally EOF case with data,
	// we have data; next read will be empty.
	// So we can just proceed.

	// Parse fields
	partRec.LbPart = line[0:8]
	partRec.LbRegion = line[8:11]
	serialStr := line[11:15]
	var v int64 = 0
	for _, c := range serialStr {
		if c >= '0' && c <= '9' {
			v = v*10 + int64(c-'0')
		} else {
			// non-digit treat as 0? but assume digits
			v = v * 10
		}
	}
	partRec.LbSerial = v

	// If err != nil we need to detect if this was EOF: we peek next read will be empty.
	// No action here; inputDone remains false.

	// Special handling: if err != nil and we had to check next read, we will set done on next call.
	// But if file ended with newline, ReadString for last line succeeded, next call will get EOF empty.
	// So logic of checking err==nil vs not is not needed for now.
	if err != nil {
		// We have just read the last line that had no trailing newline, or file ended.
		// We need to ensure next readPara will detect EOF.
		// We can check if underlying reader has no more data by peeking.
		// Instead set a pending EOF flag: if err != nil, the next read will definitely be EOF,
		// but we don't know if current line was valid. It is valid, so keep it.
		// To avoid losing the pending EOF, we don't set done now.
		// We will let next call handle it. However we need to know that next call's ReadString will return EOF empty.
		// That's fine.
		// But if the file ended with newline, err==nil now, done not set.
	}

	// If the preceding ReadString returned error and line was empty, we already returned.
	// Otherwise we have a record; ensure done flag is not set.
	// For the case where file is empty, first read returns EOF empty -> done true.
}

func processPara() {
	// MOVE SPACES TO WS-LABEL
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	// INSPECT LB-PART TALLYING FOR ALL "A"
	cnt := int64(strings.Count(partRec.LbPart, "A"))
	WsACount = cnt

	// STRING ... INTO WS-LABEL
	partRegionDelim := delimitedBySpace(partRec.LbRegion)
	partPartDelim := delimitedBySpace(partRec.LbPart)
	serialStr := formatPIC9(partRec.LbSerial, 4)

	// Build string pieces: REGION part, "-", PART part, "-", SERIAL
	var pieces []string
	pieces = append(pieces, partRegionDelim)
	pieces = append(pieces, "-")
	pieces = append(pieces, partPartDelim)
	pieces = append(pieces, "-")
	pieces = append(pieces, serialStr)

	combined := strings.Join(pieces, "")
	// STRING INTO WS-LABEL: place combined at start, keep trailing spaces from blank
	if len(combined) > 20 {
		combined = combined[:20]
	}
	WsLabel = combined + strings.Repeat(" ", 20-len(combined))

	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	WsTotalA = WsTotalA + WsACount
	WsCount = WsCount + 1

	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	// WS-LABEL is X(20) prints exactly 20 chars, " A=" literal, WS-A-COUNT PIC 99 zero padded 2
	fmt.Printf("%s A=%s\n", WsLabel, formatPIC9(WsACount, 2))

	readPara()
}

func summaryPara() {
	fmt.Printf("LABELS: %s A-TOTAL: %s\n", formatPIC9(WsCount, 3), formatPIC9(WsTotalA, 3))
}

func openInput() {
	f, err := os.Open("input.dat")
	if err != nil {
		// If file doesn't exist, treat as empty
		WsEofFlag = "Y"
		inputDone = true
		partFileReader = bufio.NewReader(strings.NewReader(""))
		return
	}
	partFileHandle = f
	partFileReader = bufio.NewReader(f)
}

func closeInput() {
	if partFileHandle != nil {
		partFileHandle.Close()
	}
}

func main() {
	mainPara()
}
